func TestNeoUserActorReceivesThreadStatusUpdatedNotification(t *testing.T) {
	rt := newNeoRuntime(&config.Config{})
	threadID := "T-019e0e6e-f3f1-7078-b5dd-748f66f8c260"
	threadActor, _ := rt.store.upsert(map[string]any{"name": "threadActor", "key": threadID, "input": map[string]any{"threadId": threadID}}, true)
	threadActor.mu.Lock()
	threadActor.title = "Live local thread"
	threadActor.messages = []neoMessage{{
		ThreadID:  threadID,
		MessageID: "M-live",
		Role:      "user",
		CreatedAt: "2026-05-31T11:00:00Z",
		Content:   []any{map[string]any{"type": "text", "text": "watch status"}},
	}}
	threadActor.mu.Unlock()

	server := httptest.NewServer(http.HandlerFunc(rt.handleHTTP))
	t.Cleanup(server.Close)

	dialer := websocket.Dialer{Subprotocols: []string{"rivet", "rivet_conn_params.%7B%22transport%22%3A%22json-rpc%22%7D", "rivet_encoding.4", "rivet_skip_ready_wait"}}
	wsURL := "ws" + strings.TrimPrefix(server.URL, "http") + "/gateway/userActor/?rvt-method=getOrCreate&rvt-key=user-local"
	conn, resp, err := dialer.Dial(wsURL, nil)
	if err != nil {
		status := 0
		if resp != nil {
			status = resp.StatusCode
		}
		t.Fatalf("gateway userActor websocket dial failed status=%d err=%v", status, err)
	}
	defer conn.Close()

	readThreadStatusUpdated := func() map[string]any {
		t.Helper()
		deadline := time.Now().Add(2 * time.Second)
		for time.Now().Before(deadline) {
			_ = conn.SetReadDeadline(time.Now().Add(time.Until(deadline)))
			_, payload, err := conn.ReadMessage()
			if err != nil {
				if netErr, ok := err.(net.Error); ok && netErr.Timeout() {
					break
				}
				t.Fatalf("read userActor notification: %v", err)
			}
			var frame map[string]any
			if err := json.Unmarshal(payload, &frame); err != nil {
				t.Fatalf("userActor notification JSON error: %v", err)
			}
			if frame["method"] != "threadStatusUpdated" {
				continue
			}
			return mapValue(frame["params"])
		}
		t.Fatal("did not receive threadStatusUpdated notification")
		return nil
	}

	threadActor.handle(map[string]any{"type": "agent_state", "state": "working"})
	params := readThreadStatusUpdated()
	if params["threadId"] != threadID || params["title"] != "Live local thread" || params["state"] != "working" || params["agentState"] != "working" {
		t.Fatalf("threadStatusUpdated params = %#v", params)
	}
	if params["lastUserMessageAt"] != "2026-05-31T11:00:00Z" {
		t.Fatalf("threadStatusUpdated lastUserMessageAt = %#v", params["lastUserMessageAt"])
	}

	parentThreadID := "T-019e1046-656d-7132-879f-390ded941c16"
	threadActor.handle(map[string]any{"type": "thread_relationships", "relationships": []any{map[string]any{
		"threadID":  parentThreadID,
		"type":      "mention",
		"role":      "parent",
		"createdAt": 1,
	}}})
	params = readThreadStatusUpdated()
	if params["threadId"] != threadID || params["parentThreadID"] != parentThreadID {
		t.Fatalf("threadStatusUpdated relationship params = %#v", params)
	}

	threadActor.archiveThread(true, nil)
	params = readThreadStatusUpdated()
	if params["threadId"] != threadID || params["archived"] != true {
		t.Fatalf("threadStatusUpdated archive params = %#v", params)
	}
}

func TestNeoUserActorReceivesThreadStatusUpdatedOnExecutorConnectDisconnect(t *testing.T) {
	rt := newNeoRuntime(&config.Config{})
	threadID := "T-019e0e6e-f3f1-7078-b5dd-748f66f8c261"
	threadActor := rt.store.ensureThreadActor(threadID)
	threadActor.mu.Lock()
	threadActor.title = "Executor local thread"
	threadActor.messages = []neoMessage{{
		ThreadID:  threadID,
		MessageID: "M-executor-local",
		Role:      "user",
		CreatedAt: "2026-05-31T12:00:00Z",
		Content:   []any{map[string]any{"type": "text", "text": "watch executor"}},
	}}
	threadActor.mu.Unlock()

	server := httptest.NewServer(http.HandlerFunc(rt.handleHTTP))
	t.Cleanup(server.Close)

	dialer := websocket.Dialer{Subprotocols: []string{"rivet", "rivet_conn_params.%7B%22transport%22%3A%22json-rpc%22%7D", "rivet_encoding.4", "rivet_skip_ready_wait"}}
	wsURL := "ws" + strings.TrimPrefix(server.URL, "http") + "/gateway/userActor/?rvt-method=getOrCreate&rvt-key=user-local"
	conn, resp, err := dialer.Dial(wsURL, nil)
	if err != nil {
		status := 0
		if resp != nil {
			status = resp.StatusCode
		}
		t.Fatalf("gateway userActor websocket dial failed status=%d err=%v", status, err)
	}
	defer conn.Close()

	readThreadStatusUpdated := func() map[string]any {
		t.Helper()
		deadline := time.Now().Add(2 * time.Second)
		for time.Now().Before(deadline) {
			_ = conn.SetReadDeadline(time.Now().Add(time.Until(deadline)))
			_, payload, err := conn.ReadMessage()
			if err != nil {
				if netErr, ok := err.(net.Error); ok && netErr.Timeout() {
					break
				}
				t.Fatalf("read userActor executor notification: %v", err)
			}
			var frame map[string]any
			if err := json.Unmarshal(payload, &frame); err != nil {
				t.Fatalf("userActor executor notification JSON error: %v", err)
			}
			if frame["method"] != "threadStatusUpdated" {
				continue
			}
			params := mapValue(frame["params"])
			if params["threadId"] != threadID {
				continue
			}
			return params
		}
		t.Fatal("did not receive threadStatusUpdated notification for executor state")
		return nil
	}

	threadActor.executorConnected(map[string]any{"executorId": "executor-test"})
	params := readThreadStatusUpdated()
	if params["title"] != "Executor local thread" || params["state"] != "idle" || params["agentState"] != "idle" {
		t.Fatalf("executor connected threadStatusUpdated params = %#v", params)
	}
	if params["hasExecutor"] != true || params["executorConnected"] != true {
		t.Fatalf("executor connected status = has:%#v connected:%#v params=%#v", params["hasExecutor"], params["executorConnected"], params)
	}
	if params["lastUserMessageAt"] != "2026-05-31T12:00:00Z" {
		t.Fatalf("executor connected lastUserMessageAt = %#v", params["lastUserMessageAt"])
	}
	snapshot, ok := threadActor.threadSnapshot()
	if !ok {
		t.Fatal("missing connected thread snapshot")
	}
	thread := neoCloudThread(snapshot)
	if thread["hasExecutor"] != true || thread["executorConnected"] != true || mapValue(thread["meta"])["executorType"] != "local-client" {
		t.Fatalf("connected cloud thread executor state = has:%#v connected:%#v meta:%#v", thread["hasExecutor"], thread["executorConnected"], thread["meta"])
	}

	threadActor.executorDisconnected(map[string]any{"message": "done"})
	params = readThreadStatusUpdated()
	if params["hasExecutor"] != false || params["executorConnected"] != false {
		t.Fatalf("executor disconnected status = has:%#v connected:%#v params=%#v", params["hasExecutor"], params["executorConnected"], params)
	}
	snapshot, ok = threadActor.threadSnapshot()
	if !ok {
		t.Fatal("missing disconnected thread snapshot")
	}
	thread = neoCloudThread(snapshot)
	if thread["hasExecutor"] != false || thread["executorConnected"] != false {
		t.Fatalf("disconnected cloud thread executor state = has:%#v connected:%#v", thread["hasExecutor"], thread["executorConnected"])
	}
	if mapValue(thread["meta"])["executorType"] != nil {
		t.Fatalf("disconnected cloud thread executorType = %#v, want absent", thread["meta"])
	}
}

