func waitForNeoMessageType(t *testing.T, conn *websocket.Conn, msgType string, timeout time.Duration) map[string]any {
	return waitForNeoMessageTypeWhere(t, conn, msgType, timeout, nil)
}

func waitForNeoMessageTypeWhere(t *testing.T, conn *websocket.Conn, msgType string, timeout time.Duration, match func(map[string]any) bool) map[string]any {
	t.Helper()
	deadline := time.Now().Add(timeout)
	for time.Now().Before(deadline) {
		msg, ok := readNeoMessage(t, conn, time.Until(deadline))
		if !ok {
			break
		}
		if msg["type"] == msgType && (match == nil || match(msg)) {
			return msg
		}
	}
	t.Fatalf("timed out waiting for websocket message type %q", msgType)
	return nil
}

func assertNoNeoMessageType(t *testing.T, conn *websocket.Conn, msgType string, timeout time.Duration) {
	t.Helper()
	deadline := time.Now().Add(timeout)
	for time.Now().Before(deadline) {
		msg, ok := readNeoMessage(t, conn, time.Until(deadline))
		if !ok {
			return
		}
		if msg["type"] == msgType {
			t.Fatalf("unexpected websocket message type %q: %#v", msgType, msg)
		}
	}
}

func waitForNeoRivetBareInit(t *testing.T, conn *websocket.Conn, timeout time.Duration) map[string]any {
	t.Helper()
	frame, ok := readNeoRivetBareServerFrame(t, conn, timeout)
	if !ok {
		t.Fatal("timed out waiting for Rivet init frame")
	}
	if frame["tag"] != "Init" {
		t.Fatalf("first Rivet frame = %#v, want Init", frame)
	}
	return mapValue(frame["val"])
}

func waitForNeoRivetBareEventType(t *testing.T, conn *websocket.Conn, msgType string, timeout time.Duration) map[string]any {
	t.Helper()
	return waitForNeoRivetBareEventTypeWhere(t, conn, msgType, timeout, nil)
}

func waitForNeoRivetBareEventTypeWhere(t *testing.T, conn *websocket.Conn, msgType string, timeout time.Duration, match func(map[string]any) bool) map[string]any {
	t.Helper()
	deadline := time.Now().Add(timeout)
	for time.Now().Before(deadline) {
		name, args, ok := readNeoRivetBareEvent(t, conn, time.Until(deadline))
		if !ok {
			break
		}
		if name != msgType {
			continue
		}
		if len(args) != 1 {
			t.Fatalf("Rivet event args for %q = %#v, want one payload", msgType, args)
		}
		payload := mapValue(args[0])
		if match == nil || match(payload) {
			return payload
		}
	}
	t.Fatalf("timed out waiting for Rivet event type %q", msgType)
	return nil
}

func waitForNeoRivetBareEventName(t *testing.T, conn *websocket.Conn, name string, timeout time.Duration) map[string]any {
	t.Helper()
	deadline := time.Now().Add(timeout)
	for time.Now().Before(deadline) {
		frame, ok := readNeoRivetBareServerFrame(t, conn, time.Until(deadline))
		if !ok {
			break
		}
		if frame["tag"] != "Event" {
			continue
		}
		val := mapValue(frame["val"])
		if val["name"] == name {
			return frame
		}
	}
	t.Fatalf("timed out waiting for Rivet event name %q", name)
	return nil
}

func waitForNeoRivetBareFrameTag(t *testing.T, conn *websocket.Conn, tag string, timeout time.Duration) map[string]any {
	t.Helper()
	deadline := time.Now().Add(timeout)
	for time.Now().Before(deadline) {
		frame, ok := readNeoRivetBareServerFrame(t, conn, time.Until(deadline))
		if !ok {
			break
		}
		if frame["tag"] == tag {
			return frame
		}
	}
	t.Fatalf("timed out waiting for Rivet frame tag %q", tag)
	return nil
}

func readNeoRivetBareEvent(t *testing.T, conn *websocket.Conn, timeout time.Duration) (string, []any, bool) {
	t.Helper()
	frame, ok := readNeoRivetBareServerFrame(t, conn, timeout)
	if !ok {
		return "", nil, false
	}
	if frame["tag"] != "Event" {
		return "", nil, true
	}
	val := mapValue(frame["val"])
	return stringValue(val["name"]), arrayValue(val["args"]), true
}

func readNeoRivetBareServerFrame(t *testing.T, conn *websocket.Conn, timeout time.Duration) (map[string]any, bool) {
	t.Helper()
	if timeout <= 0 {
		timeout = time.Millisecond
	}
	_ = conn.SetReadDeadline(time.Now().Add(timeout))
	messageType, payload, err := conn.ReadMessage()
	if err != nil {
		if netErr, ok := err.(net.Error); ok && netErr.Timeout() {
			return nil, false
		}
		t.Fatalf("read Rivet websocket frame: %v", err)
	}
	if messageType != websocket.BinaryMessage {
		t.Fatalf("Rivet message type = %d, want binary", messageType)
	}
	return decodeNeoRivetBareServerFrameForTest(t, payload), true
}

func readNeoMessage(t *testing.T, conn *websocket.Conn, timeout time.Duration) (map[string]any, bool) {
	t.Helper()
	if timeout <= 0 {
		timeout = time.Millisecond
	}
	_ = conn.SetReadDeadline(time.Now().Add(timeout))
	_, payload, err := conn.ReadMessage()
	if err != nil {
		if netErr, ok := err.(net.Error); ok && netErr.Timeout() {
			return nil, false
		}
		t.Fatalf("read websocket message: %v", err)
	}
	var msg map[string]any
	if err := json.Unmarshal(payload, &msg); err != nil {
		t.Fatalf("websocket JSON error: %v", err)
	}
	return msg, true
}

func waitForNeoActorSyncIdle(t *testing.T, actor *neoActor) {
	t.Helper()
	deadline := time.Now().Add(2 * time.Second)
	var idleSince time.Time
	for time.Now().Before(deadline) {
		actor.mu.Lock()
		running := actor.syncRunning
		pending := actor.syncPending
		actor.mu.Unlock()
		if !running && !pending {
			if idleSince.IsZero() {
				idleSince = time.Now()
			}
			if time.Since(idleSince) >= 25*time.Millisecond {
				return
			}
		} else {
			idleSince = time.Time{}
		}
		time.Sleep(10 * time.Millisecond)
	}
	t.Fatal("timed out waiting for actor sync to become idle")
}

func marshalNeoThreadForTest(t *testing.T, thread map[string]any) map[string]any {
	t.Helper()
	raw, err := json.Marshal(thread)
	if err != nil {
		t.Fatalf("marshal thread: %v", err)
	}
	var out map[string]any
	if err := json.Unmarshal(raw, &out); err != nil {
		t.Fatalf("unmarshal thread: %v", err)
	}
	return out
}

func TestNeoActorHandlesThreadStatusCompactionAndRetryEvents(t *testing.T) {
	rt := newNeoRuntime(&config.Config{})
	actor := newNeoActor(rt, "actor-test", "threadActor", "", "", neoActorRecord("actor-test", "threadActor", ""), nil)

	actor.handle(map[string]any{"type": "thread_status", "status": "merged"})
	actor.handle(map[string]any{"type": "compaction_started"})
	actor.handle(map[string]any{"type": "compaction_complete", "cutMessageId": "M-00000000000000000000aa", "createdAt": "2026-01-01T00:00:00Z"})
	actor.handle(map[string]any{"type": "retry_scheduled", "retryAt": 123, "attempt": 2, "maxAttempts": 3, "reason": "rate_limit"})

	actor.mu.Lock()
	if actor.threadStatus != "merged" {
		t.Fatalf("threadStatus = %q, want merged", actor.threadStatus)
	}
	if actor.compacting {
		t.Fatal("compacting should be false after compaction_complete")
	}
	if len(actor.compactionRecords) != 1 || stringValue(actor.compactionRecords[0]["cutMessageId"]) != "M-00000000000000000000aa" {
		t.Fatalf("compactionRecords = %#v", actor.compactionRecords)
	}
	if !actor.retryScheduled {
		t.Fatal("retryScheduled = false, want true")
	}
	actor.mu.Unlock()

	actor.handle(map[string]any{"type": "retry_cancelled"})
	actor.mu.Lock()
	defer actor.mu.Unlock()
	if actor.retryScheduled {
		t.Fatal("retryScheduled = true after retry_cancelled")
	}
}

func TestNeoActorCompactionEventsRebuildInferenceHistory(t *testing.T) {
	rt := newNeoRuntime(&config.Config{})
	threadID := "T-compaction-event-history"
	actor := newNeoActor(rt, "actor-test", "threadActor", threadID, threadID, neoActorRecord("actor-test", "threadActor", threadID), nil)
	actor.mu.Lock()
	for i := 0; i < 5; i++ {
		role := "user"
		if i%2 == 1 {
			role = "assistant"
		}
		text := fmt.Sprintf("message %02d", i)
		if i == 0 {
			text += " stale compacted prefix"
		}
		if i == 2 {
			text += " cut boundary"
		}
		actor.messages = append(actor.messages, neoMessage{
			ThreadID:  threadID,
			MessageID: fmt.Sprintf("M-%022d", i),
			Role:      role,
			Content:   []any{map[string]any{"type": "text", "text": text}},
		})
	}
	actor.rebuildHistoryLocked()
	if !strings.Contains(fmt.Sprint(actor.history), "stale compacted prefix") {
		t.Fatalf("initial history = %#v, want uncompacted prefix before event", actor.history)
	}
	actor.mu.Unlock()

	actor.handle(map[string]any{"type": "compaction_complete", "cutMessageId": "M-0000000000000000000002", "createdAt": "2026-05-30T00:00:00Z"})

	actor.mu.Lock()
	historyText := fmt.Sprint(actor.history)
	if strings.Contains(historyText, "stale compacted prefix") {
		t.Fatalf("history after compaction_complete replayed compacted prefix: %#v", actor.history)
	}
	if !strings.Contains(historyText, "message 02 cut boundary") || !strings.Contains(historyText, "message 04") {
		t.Fatalf("history after compaction_complete = %#v, want cut boundary and tail", actor.history)
	}
	actor.mu.Unlock()

	actor.handle(map[string]any{"type": "compaction_records", "records": []any{map[string]any{"cutMessageId": "M-0000000000000000000004", "createdAt": "2026-05-30T00:01:00Z"}}})

	actor.mu.Lock()
	defer actor.mu.Unlock()
	historyText = fmt.Sprint(actor.history)
	if strings.Contains(historyText, "message 02 cut boundary") {
		t.Fatalf("history after compaction_records replayed stale cut prefix: %#v", actor.history)
	}
	if !strings.Contains(historyText, "message 04") {
		t.Fatalf("history after compaction_records = %#v, want latest cut tail", actor.history)
	}
}

