func TestNeoActorHandlesClientEditMessage(t *testing.T) {
	rt := newNeoRuntime(&config.Config{})
	actor := newNeoActor(rt, "actor-test", "thread-actor", "T-test", "T-test", neoActorRecord("actor-test", "thread-actor", "T-test"), nil)
	actor.messages = []neoMessage{
		{ThreadID: "T-test", MessageID: "M-0000000000000000000001", Role: "user", Content: []any{map[string]any{"type": "text", "text": "old"}}, AgentMode: "smart", Seq: 1},
		{ThreadID: "T-test", MessageID: "M-0000000000000000000002", Role: "assistant", Content: []any{map[string]any{"type": "text", "text": "answer"}}, Seq: 2},
	}
	actor.history = []neoHistoryMessage{
		{Role: "user", Text: "old"},
		{Role: "assistant", Text: "answer"},
	}
	actor.seq = 3

	actor.handle(map[string]any{
		"type":            "client_edit_message",
		"messageId":       "M-0000000000000000000001",
		"editId":          "E-0000000000000000000001",
		"content":         []any{map[string]any{"type": "text", "text": "edited"}},
		"agentMode":       "deep",
		"reasoningEffort": "xhigh",
	})

	actor.mu.Lock()
	defer actor.mu.Unlock()
	if len(actor.messages) != 1 {
		t.Fatalf("messages len = %d, want edited message only", len(actor.messages))
	}
	if got := textFromBlocks(actor.messages[0].Content); got != "edited" {
		t.Fatalf("edited content = %q", got)
	}
	if actor.messages[0].AgentMode != "deep" || actor.messages[0].ReasoningEffort != "xhigh" {
		t.Fatalf("edited mode/effort = %q/%q", actor.messages[0].AgentMode, actor.messages[0].ReasoningEffort)
	}
	if len(actor.history) != 1 || actor.history[0].Text != "edited" {
		t.Fatalf("history = %#v", actor.history)
	}
	if actor.pendingInference == nil || actor.pendingInference.agentMode != "deep" || actor.pendingInference.reasoningEffort != "xhigh" {
		t.Fatalf("pending inference after offline edit = %#v, want deep/xhigh", actor.pendingInference)
	}
}

func TestNeoActorHandlesClientEditMessageReplacementID(t *testing.T) {
	rt := newNeoRuntime(&config.Config{})
	actor := newNeoActor(rt, "actor-test", "thread-actor", "T-test", "T-test", neoActorRecord("actor-test", "thread-actor", "T-test"), nil)
	actor.messages = []neoMessage{
		{ThreadID: "T-test", MessageID: "M-0000000000000000000001", Role: "user", Content: []any{map[string]any{"type": "text", "text": "old"}}, AgentMode: "smart", Seq: 1},
		{ThreadID: "T-test", MessageID: "M-0000000000000000000002", Role: "assistant", Content: []any{map[string]any{"type": "text", "text": "answer"}}, Seq: 2},
	}
	actor.history = []neoHistoryMessage{
		{Role: "user", Text: "old"},
		{Role: "assistant", Text: "answer"},
	}
	actor.seq = 3

	actor.handle(map[string]any{
		"type":                 "client_edit_message",
		"messageId":            "M-0000000000000000000001",
		"replacementMessageId": "M-0000000000000000000003",
		"editId":               "E-0000000000000000000001",
		"content":              []any{map[string]any{"type": "text", "text": "edited"}},
		"agentMode":            "deep",
		"reasoningEffort":      "xhigh",
	})

	actor.mu.Lock()
	defer actor.mu.Unlock()
	if len(actor.messages) != 1 {
		t.Fatalf("messages len = %d, want replacement message only", len(actor.messages))
	}
	if actor.messages[0].MessageID != "M-0000000000000000000003" {
		t.Fatalf("replacement message id = %q", actor.messages[0].MessageID)
	}
	if got := textFromBlocks(actor.messages[0].Content); got != "edited" {
		t.Fatalf("replacement content = %q", got)
	}
	if len(actor.history) != 1 || actor.history[0].Text != "edited" {
		t.Fatalf("history = %#v", actor.history)
	}
	if actor.pendingInference == nil || actor.pendingInference.agentMode != "deep" || actor.pendingInference.reasoningEffort != "xhigh" {
		t.Fatalf("pending inference after offline edit = %#v, want deep/xhigh", actor.pendingInference)
	}
	if len(actor.replayEvents) < 2 {
		t.Fatalf("replay events = %#v, want truncate and add", actor.replayEvents)
	}
	truncated := actor.replayEvents[len(actor.replayEvents)-2].Payload
	added := actor.replayEvents[len(actor.replayEvents)-1].Payload
	if truncated["type"] != "thread_truncated" || stringValue(truncated["truncateFromMessage"]) != "M-0000000000000000000001" {
		t.Fatalf("truncate event = %#v, want original message truncation", truncated)
	}
	if added["type"] != "message_added" {
		t.Fatalf("added event = %#v, want message_added", added)
	}
	addedMessage := mapValue(added["message"])
	if stringValue(addedMessage["messageId"]) != "M-0000000000000000000003" {
		t.Fatalf("added message = %#v, want replacement id", addedMessage)
	}
	if numberFrom(truncated["seq"]) >= numberFrom(added["seq"]) {
		t.Fatalf("event order seqs = truncate %#v add %#v, want truncate before add", truncated, added)
	}
}

func TestNeoActorRejectsClientEditMessageReusedReplacementID(t *testing.T) {
	rt := newNeoRuntime(&config.Config{})
	actor := newNeoActor(rt, "actor-test", "thread-actor", "T-test", "T-test", neoActorRecord("actor-test", "thread-actor", "T-test"), nil)
	actor.messages = []neoMessage{
		{ThreadID: "T-test", MessageID: "M-0000000000000000000001", Role: "user", Content: []any{map[string]any{"type": "text", "text": "first"}}, AgentMode: "smart", Seq: 1},
		{ThreadID: "T-test", MessageID: "M-0000000000000000000002", Role: "assistant", Content: []any{map[string]any{"type": "text", "text": "answer"}}, Seq: 2},
		{ThreadID: "T-test", MessageID: "M-0000000000000000000003", Role: "user", Content: []any{map[string]any{"type": "text", "text": "old"}}, AgentMode: "smart", Seq: 3},
	}
	actor.history = []neoHistoryMessage{
		{Role: "user", Text: "first"},
		{Role: "assistant", Text: "answer"},
		{Role: "user", Text: "old"},
	}
	actor.seq = 4

	actor.handle(map[string]any{
		"type":                 "client_edit_message",
		"messageId":            "M-0000000000000000000003",
		"replacementMessageId": "M-0000000000000000000001",
		"editId":               "E-0000000000000000000001",
		"content":              []any{map[string]any{"type": "text", "text": "edited"}},
		"agentMode":            "deep",
		"reasoningEffort":      "xhigh",
	})

	actor.mu.Lock()
	defer actor.mu.Unlock()
	if len(actor.messages) != 3 {
		t.Fatalf("messages len = %d, want original messages unchanged", len(actor.messages))
	}
	if got := actor.messages[0].MessageID; got != "M-0000000000000000000001" {
		t.Fatalf("first message id = %q", got)
	}
	if got := actor.messages[2].MessageID; got != "M-0000000000000000000003" {
		t.Fatalf("edited message id = %q", got)
	}
	if got := textFromBlocks(actor.messages[2].Content); got != "old" {
		t.Fatalf("edited message content = %q, want original content", got)
	}
	if actor.pendingInference != nil {
		t.Fatalf("pending inference = %#v, want nil after rejected edit", actor.pendingInference)
	}
}

func TestNeoActorUpdateSettingsPreservesModeWhenPatchOmitsAgentMode(t *testing.T) {
	rt := newNeoRuntime(&config.Config{})
	actor := newNeoActor(rt, "actor-test", "thread-actor", "T-test", "T-test", neoActorRecord("actor-test", "thread-actor", "T-test"), nil)
	actor.settings = map[string]any{"agentMode": "deep", "reasoning.effort": "xhigh"}
	actor.currentAgentMode = "deep"
	actor.currentReasoningEffort = "xhigh"

	actor.updateSettings(map[string]any{"tools.enable": []any{"read_thread"}})

	actor.mu.Lock()
	if actor.currentAgentMode != "deep" {
		t.Fatalf("currentAgentMode = %q, want deep", actor.currentAgentMode)
	}
	if actor.settings["agentMode"] != "deep" || actor.settings["reasoning.effort"] != "xhigh" {
		t.Fatalf("settings lost existing mode/effort: %#v", actor.settings)
	}
	actor.mu.Unlock()

	actor.updateSettings(map[string]any{"agentMode": "smart"})
	actor.mu.Lock()
	if actor.currentAgentMode != "smart" || actor.settings["agentMode"] != "smart" {
		t.Fatalf("explicit smart update was not applied: mode=%q settings=%#v", actor.currentAgentMode, actor.settings)
	}
	if actor.currentReasoningEffort != "high" || actor.settings["reasoning.effort"] != "high" {
		t.Fatalf("smart update did not reset effort to default: effort=%q settings=%#v", actor.currentReasoningEffort, actor.settings)
	}
	actor.mu.Unlock()

	actor.updateSettings(map[string]any{"agentMode": "rush"})
	actor.mu.Lock()
	defer actor.mu.Unlock()
	if actor.currentAgentMode != "rush" || actor.currentReasoningEffort != "none" {
		t.Fatalf("rush update should reset effort to binary default: mode=%q effort=%q", actor.currentAgentMode, actor.currentReasoningEffort)
	}
	if actor.settings["reasoning.effort"] != "none" {
		t.Fatalf("rush settings did not keep binary default effort: %#v", actor.settings)
	}
}

func TestNeoActorReasoningEffortDefaultsByMode(t *testing.T) {
	rt := newNeoRuntime(&config.Config{})
	actor := newNeoActor(rt, "actor-test", "thread-actor", "T-test", "T-test", neoActorRecord("actor-test", "thread-actor", "T-test"), nil)
	actor.currentAgentMode = "smart"
	actor.currentReasoningEffort = "high"
	actor.messages = []neoMessage{{Role: "user", AgentMode: "smart", ReasoningEffort: "max"}}

	if got := actor.reasoningEffortForModeLocked("rush"); got != "none" {
		t.Fatalf("rush effort = %q, want none", got)
	}
	if got := actor.reasoningEffortForModeLocked("agg-man"); got != "none" {
		t.Fatalf("agg-man effort = %q, want none", got)
	}
	if got := actor.reasoningEffortForModeLocked("deep"); got != "medium" {
		t.Fatalf("deep effort = %q, want medium", got)
	}
	if got := actor.reasoningEffortForModeLocked("smart"); got != "high" {
		t.Fatalf("smart effort = %q, want high", got)
	}
	if got := actor.reasoningEffortForModeLocked("frontier"); got != "" {
		t.Fatalf("unknown mode effort = %q, want empty", got)
	}
	if got := actor.reasoningEffortForModeLocked("nostromo"); got != "low" {
		t.Fatalf("nostromo effort = %q, want low", got)
	}
	if got := actor.reasoningEffortForModeLocked("low"); got != "medium" {
		t.Fatalf("low effort = %q, want medium", got)
	}
	if got := actor.reasoningEffortForModeLocked("medium"); got != "medium" {
		t.Fatalf("medium effort = %q, want medium", got)
	}
	if got := actor.reasoningEffortForModeLocked("high"); got != "xhigh" {
		t.Fatalf("high effort = %q, want xhigh", got)
	}
	if got := actor.reasoningEffortForModeLocked("ultra"); got != "high" {
		t.Fatalf("ultra effort = %q, want high", got)
	}
}

func TestNeoReasoningDefaultsAndLevelsMatchAuditBaseline(t *testing.T) {
	baseline := ampBinaryParityBaselineForTest(t)
	if len(baseline.Signals.AgentModeProfiles) == 0 {
		t.Fatal("Amp binary parity baseline has no agent_mode_profiles")
	}
	for _, profile := range baseline.Signals.AgentModeProfiles {
		t.Run(profile.Name, func(t *testing.T) {
			if got := defaultNeoReasoningEffort(profile.Name); got != profile.ReasoningEffort {
				t.Fatalf("default reasoning effort = %q, want %q from Amp binary baseline", got, profile.ReasoningEffort)
			}
			if profile.ReasoningEffort != "" && !neoReasoningEffortAllowedForMode(profile.Name, profile.ReasoningEffort) {
				t.Fatalf("binary default reasoning effort %q is not allowed for mode %q", profile.ReasoningEffort, profile.Name)
			}
			for _, level := range profile.ReasoningLevels {
				if !neoReasoningEffortAllowedForMode(profile.Name, level) {
					t.Fatalf("binary reasoning level %q is not allowed for mode %q", level, profile.Name)
				}
			}
		})
	}
}

func TestNeoAgentModeCoverageHasExplicitOwnership(t *testing.T) {
	baseline := ampBinaryParityBaselineForTest(t)
	if len(baseline.Signals.AgentModeCoverage) == 0 {
		t.Fatal("Amp binary parity baseline has no agent_mode_coverage")
	}
	coverage := map[string]string{
		"agg-man":  "server-only",
		"deep":     "local-runtime",
		"high":     "local-runtime",
		"large":    "local-runtime",
		"low":      "local-runtime",
		"medium":   "local-runtime",
		"nostromo": "local-runtime",
		"review":   "local-runtime",
		"rush":     "local-runtime",
		"smart":    "local-runtime",
		"ultra":    "local-runtime",
	}
	for _, mode := range baseline.Signals.AgentModeCoverage {
		t.Run(mode.Name, func(t *testing.T) {
			if got := coverage[mode.Name]; got != mode.Scope {
				t.Fatalf("agent mode %q scope = %q, want %q from Amp binary baseline", mode.Name, got, mode.Scope)
			}
			if mode.Scope == "local-runtime" {
				route := selectNeoModelRoute(mode.Name, nil)
				if route.Provider == "" || route.Model == "" {
					t.Fatalf("local runtime mode %q has no runtime model route: %+v", mode.Name, route)
				}
			}
		})
	}
}

func TestNeoToolRunStatusesMatchAuditBaseline(t *testing.T) {
	baseline := ampBinaryParityBaselineForTest(t)
	if len(baseline.Signals.ToolRunCoverage) == 0 {
		t.Fatal("Amp binary parity baseline has no tool_run_coverage")
	}
	for _, status := range baseline.Signals.ToolRunCoverage {
		t.Run(status.Name, func(t *testing.T) {
			wantTerminal := strings.HasPrefix(status.Area, "terminal-")
			if got := neoTerminalToolRunStatus(status.Name); got != wantTerminal {
				t.Fatalf("terminal status classification for %q = %v, want %v from Amp binary baseline area %q", status.Name, got, wantTerminal, status.Area)
			}
			if !neoKnownToolRunStatus(status.Name) {
				t.Fatalf("tool run status %q from Amp binary baseline is not accepted by runtime", status.Name)
			}
			run, ok := neoToolProgressRun(map[string]any{
				"status": status.Name,
				"progress": map[string]any{
					"message": "sample",
				},
			}, nil)
			if !ok {
				t.Fatalf("tool_progress with binary status %q was rejected", status.Name)
			}
			if got := stringValue(run["status"]); got != status.Name {
				t.Fatalf("tool_progress status = %q, want %q", got, status.Name)
			}
		})
	}
}

func TestNeoToolCancelReasonsMatchAuditBaseline(t *testing.T) {
	baseline := ampBinaryParityBaselineForTest(t)
	if len(baseline.Signals.ToolCancelCoverage) == 0 {
		// gaac893 removed the client-side cancel-reason taxonomy; cancel text
		// rendering for legacy reasons is exercised below only when present.
		return
	}
	for _, reason := range baseline.Signals.ToolCancelCoverage {
		t.Run(reason.Name, func(t *testing.T) {
			text := neoCancelledToolRunReasonText(reason.Name)
			if strings.TrimSpace(text) == "" {
				t.Fatalf("cancel reason %q from Amp binary baseline produced empty text", reason.Name)
			}
			if strings.Contains(text, reason.Name) {
				t.Fatalf("cancel reason %q leaked raw protocol reason into model-facing text: %q", reason.Name, text)
			}
		})
	}
}

