func TestNeoActorToolsForModeFollowBinaryModeOrder(t *testing.T) {
	rt := newNeoRuntime(&config.Config{})
	actor := newNeoActor(rt, "actor-test", "thread-actor", "T-test", "T-test", neoActorRecord("actor-test", "thread-actor", "T-test"), nil)
	binaryNostromoOrder := []string{
		"finder", "shell_command", "shell_command_status", "create_file", "edit_file", "web_search", "read_web_page", "read_thread", "find_thread", "skill", "load_plugin", "oracle", "librarian", "Task", "view_media", "painter", "read_mcp_resource", "archive_current_thread", "manage_automation", "slack_write", "slack_read", "send_message_to_agg", "apply_patch",
	}
	rawTools := []any{map[string]any{"name": "external_tool", "source": map[string]any{"plugin": "test"}}}
	for i := len(binaryNostromoOrder) - 1; i >= 0; i-- {
		rawTools = append(rawTools, map[string]any{"name": binaryNostromoOrder[i]})
	}
	actor.registerTools(rawTools)

	tools := actor.toolsForModeLocked("nostromo", nil)
	names := make([]string, 0, len(tools))
	for _, tool := range tools {
		names = append(names, tool.Name)
	}
	want := append(append([]string(nil), binaryNostromoOrder...), "external_tool")
	if !reflect.DeepEqual(names, want) {
		t.Fatalf("nostromo tool order = %#v, want %#v", names, want)
	}
}

func TestNeoActorExposesSyntheticLocalToolsWhenExecutorOmitsThem(t *testing.T) {
	rt := newNeoRuntime(&config.Config{})
	actor := newNeoActor(rt, "actor-test", "thread-actor", "T-test", "T-test", neoActorRecord("actor-test", "thread-actor", "T-test"), nil)
	actor.executorBootstrapComplete = true
	actor.registerTools([]any{
		map[string]any{"name": "shell_command"},
		map[string]any{"name": "apply_patch"},
		map[string]any{"name": "web_search"},
		map[string]any{"name": "read_web_page"},
		map[string]any{"name": "chart"},
		map[string]any{"name": "skill"},
		map[string]any{"name": "view_media"},
		map[string]any{"name": "painter"},
	})

	tools := actor.toolsForModeLocked("deep", nil)
	byName := map[string]neoToolSpec{}
	names := make([]string, 0, len(tools))
	for _, tool := range tools {
		byName[tool.Name] = tool
		names = append(names, tool.Name)
	}

	for _, name := range []string{"finder", "oracle", "librarian", "Task", "read_thread"} {
		spec, ok := byName[name]
		if !ok {
			t.Fatalf("synthetic local tool %s was not exposed to the model: %v", name, names)
		}
		if strings.TrimSpace(spec.Description) == "" || len(spec.InputSchema) == 0 {
			t.Fatalf("synthetic local tool %s exposed without a real spec (desc/schema empty)", name)
		}
	}
	readThreadProperties := mapValue(byName["read_thread"].InputSchema["properties"])
	if _, ok := readThreadProperties["threadID"]; !ok {
		t.Fatalf("read_thread schema missing threadID property: %#v", byName["read_thread"].InputSchema)
	}
	if _, ok := readThreadProperties["goal"]; !ok {
		t.Fatalf("read_thread schema missing goal property: %#v", byName["read_thread"].InputSchema)
	}
	if _, ok := readThreadProperties["question"]; ok {
		t.Fatalf("read_thread schema exposed non-binary question property: %#v", byName["read_thread"].InputSchema)
	}
	if required := arrayValue(byName["read_thread"].InputSchema["required"]); !slices.Equal(neoStringSlice(required), []string{"goal"}) {
		t.Fatalf("read_thread required = %#v, want goal only", required)
	}
	for _, name := range []string{"shell_command", "apply_patch", "skill", "view_media", "painter"} {
		if _, ok := byName[name]; !ok {
			t.Fatalf("registered tool %s missing from exposed set: %v", name, names)
		}
	}
	for _, name := range []string{"find_thread", "send_message_to_agg"} {
		if _, ok := byName[name]; ok {
			t.Fatalf("tool %s should not be synthesized (not locally executable)", name)
		}
	}
}

func TestNeoActorAllowsExternalToolsNamedLikeBuiltins(t *testing.T) {
	rt := newNeoRuntime(&config.Config{})
	actor := newNeoActor(rt, "actor-test", "thread-actor", "T-test", "T-test", neoActorRecord("actor-test", "thread-actor", "T-test"), nil)
	actor.registerTools([]any{
		map[string]any{"name": "Bash", "source": map[string]any{"plugin": "test-plugin"}},
		map[string]any{"name": "Read", "source": "builtin"},
	})

	source := mapValue(actor.tools["Bash"].Meta["source"])
	if source["plugin"] != "test-plugin" {
		t.Fatalf("top-level source was not preserved in tool meta: %#v", actor.tools["Bash"].Meta)
	}

	names := map[string]bool{}
	for _, tool := range actor.inferenceRequestLocked("deep", "", "").Tools {
		names[tool.Name] = true
	}
	if !names["Bash"] {
		t.Fatalf("external Bash tool was filtered by built-in mode table: %#v", names)
	}
	if names["Read"] {
		t.Fatalf("builtin Read tool bypassed deep mode filtering: %#v", names)
	}
}

func TestNeoActorPreservesBinaryTopLevelToolMetadata(t *testing.T) {
	rt := newNeoRuntime(&config.Config{})
	actor := newNeoActor(rt, "actor-test", "thread-actor", "T-test", "T-test", neoActorRecord("actor-test", "thread-actor", "T-test"), nil)
	actor.registerTools([]any{
		map[string]any{"name": "code_review", "source": "builtin", "deferred": true},
		map[string]any{"name": "plugin_custom", "pluginName": "custom-plugin"},
		map[string]any{"name": "skill", "skillNames": []any{"code-review"}},
	})

	if deferred, _ := actor.tools["code_review"].Meta["deferred"].(bool); !deferred {
		t.Fatalf("top-level deferred was not preserved: %#v", actor.tools["code_review"].Meta)
	}
	if source := stringValue(actor.tools["code_review"].Meta["source"]); source != "builtin" {
		t.Fatalf("top-level source was not preserved: %#v", actor.tools["code_review"].Meta)
	}
	pluginSource := mapValue(actor.tools["plugin_custom"].Meta["source"])
	if pluginSource["plugin"] != "custom-plugin" {
		t.Fatalf("pluginName did not become plugin source: %#v", actor.tools["plugin_custom"].Meta)
	}
	if names := neoSkillNamesFromAny(actor.tools["skill"].Meta["skillNames"]); len(names) != 1 || names[0] != "code-review" {
		t.Fatalf("top-level skillNames were not preserved: %#v", actor.tools["skill"].Meta)
	}

	names := map[string]bool{}
	for _, tool := range actor.inferenceRequestLocked("smart", "", "").Tools {
		names[tool.Name] = true
	}
	if names["code_review"] {
		t.Fatalf("non-binary deferred tool was included: %#v", names)
	}
	if !names["plugin_custom"] || !names["skill"] {
		t.Fatalf("binary top-level metadata did not affect tool inclusion: %#v", names)
	}
}

